-- =====================================================
-- REPORTING SERVICE
-- Handles:
-- 1. generated reports history
-- 2. exported PDF/CSV reports
-- 3. dashboard statistics based on existing tables
-- =====================================================


-- =====================================================
-- TABLE: generated_reports
-- Stores reports generated by admin or manager
-- Example: daily transactions report, agency performance report
-- =====================================================
CREATE TABLE generated_reports (
    id BIGINT PRIMARY KEY AUTO_INCREMENT,

    -- User who generated the report
    generated_by BIGINT NOT NULL,

    -- Optional agency concerned by the report
    -- NULL means global report for admin
    agency_id BIGINT NULL,

    -- Report type:
    -- DAILY_TRANSACTIONS / MONTHLY_TRANSACTIONS
    -- AGENCY_PERFORMANCE / COMMISSIONS / CASH_CLOSURE
    report_type VARCHAR(50) NOT NULL,

    -- Export format: PDF / CSV / XLSX
    format VARCHAR(20) NOT NULL,

    -- Start date of report period
    period_start DATE NOT NULL,

    -- End date of report period
    period_end DATE NOT NULL,

    -- File path or URL of generated report
    file_path VARCHAR(255),

    -- Report generation status: GENERATED / FAILED
    status VARCHAR(50) NOT NULL DEFAULT 'GENERATED',

    -- Generation timestamp
    generated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT fk_report_generated_by
        FOREIGN KEY (generated_by) REFERENCES users(id),

    CONSTRAINT fk_report_agency
        FOREIGN KEY (agency_id) REFERENCES agencies(id)
);


--Most dashboard data should be calculated using SQL queries/views, not stored repeatedly.

--Examples:

-- Daily transfer volume
SELECT 
    DATE(sent_at) AS day,
    COUNT(*) AS total_transfers,
    SUM(amount) AS total_amount,
    SUM(fee_amount) AS total_fees
FROM transfers
GROUP BY DATE(sent_at);


-- Agency performance
SELECT 
    a.id,
    a.name,
    COUNT(t.id) AS total_transfers,
    SUM(t.amount) AS total_amount,
    SUM(t.fee_amount) AS total_fees
FROM agencies a
LEFT JOIN transfers t ON t.source_agency_id = a.id
GROUP BY a.id, a.name;


-- Cash discrepancies
SELECT 
    fd.id,
    acs.session_date,
    fd.difference_amount,
    fd.discrepancy_type,
    fd.status
FROM fund_discrepancies fd
JOIN agent_cash_sessions acs ON fd.cash_session_id = acs.id;